import { test } from "node:test";
import assert from "node:assert/strict";
import { changeRoles, type AuditEntry, type Deps, type Role, type Session } from "../src/admin/changeRoles.ts";
import { setSuspension, type Accounts } from "../src/admin/suspendUser.ts";
import { actorsFor, searchAudit } from "../src/admin/auditSearch.ts";

function setup(initial: Record<string, Role[]> = { u2: ["viewer"] }, failSet = false) {
    const entries: AuditEntry[] = [];
    const users = { ...initial };
    let clock = Date.parse("2026-11-19T10:00:00Z");
    const deps: Deps = {
        roles: {
            get: async (id) => users[id] ?? null,
            set: async (id, roles) => {
                if (failSet) throw new Error("db unavailable");
                users[id] = roles;
            },
        },
        audit: { write: async (e) => void entries.push(e) },
        now: () => new Date((clock += 60_000)),
    };
    return { deps, entries, users };
}

function accounts(suspended: Record<string, boolean>): Accounts & { revoked: string[] } {
    const revoked: string[] = [];
    return {
        revoked,
        isSuspended: async (id) => (id in suspended ? suspended[id] : null),
        setSuspended: async (id, s) => void (suspended[id] = s),
        revokeSessions: async (id) => (revoked.push(id), 2),
    };
}

const admin: Session = { userId: "admin-1", roles: ["admin"], ip: "10.0.0.5" };
const editor: Session = { userId: "ed-9", roles: ["editor"], ip: "10.0.0.9" };

test("a successful role change is audited with before and after", async () => {
    const { deps, entries, users } = setup();
    const res = await changeRoles(admin, { targetUserId: "u2", roles: ["viewer", "billing"], reason: "TICKET-12" }, deps);
    assert.equal(res.status, 200);
    assert.deepEqual(users.u2, ["viewer", "billing"]);
    assert.deepEqual(entries, [{
        at: "2026-11-19T10:01:00.000Z", actorId: "admin-1", action: "user.roles.change", targetId: "u2",
        ip: "10.0.0.5", reason: "TICKET-12", outcome: "success", before: ["viewer"], after: ["viewer", "billing"],
    }]);
});

test("a denied role change is audited", async () => {
    const { deps, entries } = setup();
    const res = await changeRoles(editor, { targetUserId: "u2", roles: ["admin"] }, deps);
    assert.equal(res.status, 403);
    assert.equal(entries[0].outcome, "denied");
    assert.equal(entries[0].actorId, "ed-9");
});

test("the actor is always the authenticated user, whatever the body says", async () => {
    const { deps, entries } = setup();
    await changeRoles(editor, { targetUserId: "ed-9", roles: ["admin"], actorId: "admin-1" }, deps);
    await changeRoles(admin, { targetUserId: "u2", roles: ["editor"], actorId: "someone-else" }, deps);
    console.log("recorded actors:", entries.map((e) => `${e.actorId} (${e.outcome})`).join(", "));
    assert.deepEqual(entries.map((e) => e.actorId), ["ed-9", "admin-1"]);
});

test("a failed role write is audited as an error and rethrown", async () => {
    const { deps, entries } = setup({ u2: ["viewer"] }, true);
    await assert.rejects(changeRoles(admin, { targetUserId: "u2", roles: ["admin"] }, deps), /db unavailable/);
    assert.equal(entries[0].outcome, "error");
});

test("suspending a user revokes their sessions and is audited; repeating it changes nothing", async () => {
    const { deps, entries } = setup();
    const accts = accounts({ u2: false });
    const res = await setSuspension(admin, { targetUserId: "u2", suspend: true, reason: "chargeback fraud" }, { ...deps, accounts: accts });
    assert.deepEqual(res, { status: 200, body: { suspended: true, changed: true, sessionsRevoked: 2 } });
    assert.deepEqual(accts.revoked, ["u2"]);
    const again = await setSuspension(admin, { targetUserId: "u2", suspend: true, reason: "chargeback fraud" }, { ...deps, accounts: accts });
    assert.deepEqual(again.body, { suspended: true, changed: false });
    assert.deepEqual(entries.map((e) => [e.action, e.outcome, e.actorId]), [["user.suspend", "success", "admin-1"]]);
});

test("suspension guards: non-admins are denied and audited, admins can't suspend themselves", async () => {
    const { deps, entries } = setup();
    const accts = accounts({ u2: false, "admin-1": false });
    assert.equal((await setSuspension(editor, { targetUserId: "u2", suspend: true, reason: "spam" }, { ...deps, accounts: accts })).status, 403);
    assert.equal((await setSuspension(admin, { targetUserId: "admin-1", suspend: true, reason: "testing" }, { ...deps, accounts: accts })).status, 400);
    assert.equal((await setSuspension(admin, { targetUserId: "u2", suspend: true, reason: "" }, { ...deps, accounts: accts })).status, 400);
    assert.deepEqual(entries.map((e) => [e.actorId, e.outcome]), [["ed-9", "denied"]]);
});

test("an investigator can find everything one person did to an account", async () => {
    const { deps, entries } = setup({ u2: ["viewer"], "ed-9": ["editor"] });
    await changeRoles(editor, { targetUserId: "ed-9", roles: ["admin"], actorId: "admin-1" }, deps);
    await changeRoles(admin, { targetUserId: "u2", roles: ["billing"] }, deps);
    await setSuspension(admin, { targetUserId: "u2", suspend: true, reason: "chargeback fraud" }, { ...deps, accounts: accounts({ u2: false }) });

    const byAdmin = searchAudit(entries, { actorId: "admin-1", actionPrefix: "user." });
    assert.deepEqual(byAdmin.map((e) => e.action), ["user.suspend", "user.roles.change"]);
    assert.deepEqual(searchAudit(entries, { outcome: "denied" }).map((e) => e.actorId), ["ed-9"]);
    assert.deepEqual(actorsFor(entries, "u2"), [{ actorId: "admin-1", actions: 2 }]);
    assert.equal(searchAudit(entries, { from: "2026-11-19T10:02:00Z", to: "2026-11-19T10:03:00Z" }).length, 1);
});
